def LargeOrderPromo(order):
    """
        Calculate the discount based on the number of different products in the order.If the quantity of different products in the order reaches 10 or more, the entire order will enjoy a 7% discount.
        :param order: object, the order to apply the discount to
        :return: float, discount amount
        >>> customer = {'name': 'John Doe', 'fidelity': 1200}
        >>> cart = [{'product': 'product', 'quantity': 14, 'price': 23.5}]
        >>> order = DiscountStrategy(customer, cart, DiscountStrategy.LargeOrderPromo)
        >>> DiscountStrategy.LargeOrderPromo(order)
        0.0
        """
    discount = 0.0
    if self.promotion is None:
        return discount
    if self.promotion == DiscountStrategy.FidelityPromo:
        if self.customer['fidelity'] >= 1000:
            discount += 0.05 * sum((item['quantity'] * item['price'] for item in self.cart))
        else:
            discount = 0.0
    elif self.promotion == DiscountStrategy.BulkItemPromo:
        for item in self.cart:
            if item['quantity'] >= 20:
                discount += 0.1 * item['quantity'] * item['price']
        if discount >= 0.05 * sum((item['quantity'] * item['price'] for item in self.cart)):
            discount = 0.05 * sum((item['quantity'] * item['price'] for item in self.cart))
    elif self.promotion == DiscountStrategy.LargeOrderPromo:
        if len(set([item['product'] for item in self.cart])) >= 10:
            discount += 0.07 * sum((item['quantity'] * item['price'] for item in self.cart))
    else:
        discount = 0.0
    return discount

